37	    Owner toOwner(OwnerFieldsDto ownerDto);
38	
39	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
40	
41	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
42	
43	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
44	        OwnerPageDto ownerPageDto = new OwnerPageDto();
45	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
