3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Sets {@code bulkSignupWarning} to {@code true} when more than {@link #BULK_SIGNUP_THRESHOLD}
9	 * owners have already been created for this owner's registration day, otherwise {@code false}. The
10	 * day is the owner's {@code registrationDate}, which {@link BuildOwner} has already rolled forward
11	 * off any weekend, so this matches the accumulation counted by {@link RejectOverDailyLimit}. Runs
12	 * before the owner is saved, so {@link OwnerRepository#findAll()} sees only the owners that existed
13	 * before this create.
14	 */
15	public class FlagBulkSignup {
16	
17	    /** The warning is raised once strictly more than this many owners already exist for the day. */
18	    static final int BULK_SIGNUP_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (owner.getRegistrationDate() != null
24	                    && owner.getRegistrationDate().equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        owner.setBulkSignupWarning(count > BULK_SIGNUP_THRESHOLD);
29	    }
30	}
